import { GoogleGenAI } from "@google/genai";
import { AspectRatio } from "../types";

export const generateProductImage = async (
  productDescription: string,
  stylePrompt: string,
  aspectRatio: AspectRatio,
  productBase64?: string
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  // Custom instruction based on whether we have a source image or just text
  const basePrompt = productBase64 
    ? `Take the product shown in this image and place it in a new professional scene: ${stylePrompt}. Maintain the exact product details and shape. Additional details: ${productDescription}. No text in the final image.`
    : `${stylePrompt} Product description: ${productDescription}. The image should strictly follow the style but focus on the product described. No text in the image.`;

  const contents: any = {
    parts: [
      { text: basePrompt }
    ]
  };

  if (productBase64) {
    // Remove data:image/png;base64, prefix if exists
    const cleanBase64 = productBase64.split(',')[1] || productBase64;
    contents.parts.unshift({
      inlineData: {
        data: cleanBase64,
        mimeType: 'image/png'
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: contents,
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        const base64EncodeString = part.inlineData.data;
        return `data:image/png;base64,${base64EncodeString}`;
      }
    }

    throw new Error("لم يتم العثور على صورة في الاستجابة");
  } catch (error) {
    console.error("خطأ في إنشاء الصورة:", error);
    throw error;
  }
};

import React, { useState, useRef, useCallback } from 'react';
import { MARKETING_STYLES, ASPECT_RATIOS } from './constants';
import { AspectRatio, GeneratedImage, MarketingStyle } from './types';
import StyleCard from './components/StyleCard';
import { generateProductImage } from './services/geminiService';

const App: React.FC = () => {
  const [description, setDescription] = useState('');
  const [selectedStyle, setSelectedStyle] = useState<MarketingStyle>(MARKETING_STYLES[0]);
  const [selectedRatio, setSelectedRatio] = useState<AspectRatio>("1:1");
  const [isGenerating, setIsGenerating] = useState(false);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [error, setError] = useState<string | null>(null);

  // State for user product image
  const [productImage, setProductImage] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProductImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setShowCamera(true);
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setError('لا يمكن الوصول إلى الكاميرا. تأكد من منح الأذونات اللازمة.');
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0);
        setProductImage(canvas.toDataURL('image/png'));
        stopCamera();
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      setShowCamera(false);
    }
  };

  const handleGenerate = async () => {
    if (!description.trim() && !productImage) {
      setError('يرجى إدخال وصف للمنتج أو إضافة صورة له');
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const imageUrl = await generateProductImage(
        description,
        selectedStyle.promptPrefix,
        selectedRatio,
        productImage || undefined
      );

      const newImage: GeneratedImage = {
        url: imageUrl,
        prompt: description || `صورة منتج بأسلوب ${selectedStyle.name}`,
        style: selectedStyle.name,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImage, ...prev]);
    } catch (err) {
      setError('حدث خطأ أثناء إنشاء الصورة. يرجى المحاولة مرة أخرى.');
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = (url: string, index: number) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `product-image-${index}.png`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-20">
      {/* Header */}
      <header className="sticky top-0 z-50 glass-effect py-4 px-6 border-b border-gray-200 mb-8">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-l from-blue-700 to-blue-500">
              مصمم الصور التسويقية
            </h1>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Left Column: Input Form */}
        <div className="lg:col-span-5 space-y-6">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
              إعداد المنتج
            </h2>

            <div className="space-y-6">
              {/* Product Image Section */}
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">صورة المنتج (اختياري)</label>
                {!productImage ? (
                  <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="flex flex-col items-center justify-center p-4 bg-blue-50 border-2 border-dashed border-blue-200 rounded-2xl hover:bg-blue-100 transition-colors group"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500 mb-2 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                      </svg>
                      <span className="text-xs font-bold text-blue-700">رفع صورة</span>
                    </button>
                    <button 
                      onClick={startCamera}
                      className="flex flex-col items-center justify-center p-4 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl hover:bg-gray-100 transition-colors group"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-gray-400 mb-2 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                      </svg>
                      <span className="text-xs font-bold text-gray-500">التصوير الآن</span>
                    </button>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileUpload} 
                    />
                  </div>
                ) : (
                  <div className="relative rounded-2xl overflow-hidden aspect-video bg-gray-100 border border-gray-200">
                    <img src={productImage} alt="User product" className="w-full h-full object-contain" />
                    <button 
                      onClick={() => setProductImage(null)}
                      className="absolute top-2 left-2 bg-red-500 text-white p-2 rounded-full shadow-lg hover:bg-red-600 transition-colors"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                      </svg>
                    </button>
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">وصف المنتج</label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="مثال: ساعة يد، عبوة عطر، حذاء رياضي..."
                  className="w-full h-24 p-4 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none text-right"
                  dir="rtl"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-3">نمط الإخراج المفضل</label>
                <div className="grid grid-cols-2 gap-3">
                  {MARKETING_STYLES.map((style) => (
                    <StyleCard
                      key={style.id}
                      style={style}
                      isSelected={selectedStyle.id === style.id}
                      onClick={() => setSelectedStyle(style)}
                    />
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-3">أبعاد الصورة</label>
                <div className="flex flex-wrap gap-2">
                  {ASPECT_RATIOS.map((ratio) => (
                    <button
                      key={ratio.value}
                      onClick={() => setSelectedRatio(ratio.value as AspectRatio)}
                      className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                        selectedRatio === ratio.value
                          ? 'bg-blue-600 text-white shadow-md'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                      }`}
                    >
                      {ratio.label}
                    </button>
                  ))}
                </div>
              </div>

              {error && (
                <div className="p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-sm flex items-center gap-2">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  {error}
                </div>
              )}

              <button
                onClick={handleGenerate}
                disabled={isGenerating}
                className={`w-full py-4 rounded-2xl font-bold text-lg shadow-lg transition-all flex items-center justify-center gap-3 ${
                  isGenerating 
                  ? 'bg-gray-300 cursor-not-allowed text-gray-500' 
                  : 'bg-gradient-to-r from-blue-700 to-blue-600 text-white hover:shadow-xl active:scale-95'
                }`}
              >
                {isGenerating ? (
                  <>
                    <svg className="animate-spin h-6 w-6 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    جاري التصميم...
                  </>
                ) : (
                  <>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                    {productImage ? 'تحويل صورتي إلى إعلان' : 'إنشاء صورة احترافية'}
                  </>
                )}
              </button>
            </div>
          </section>
        </div>

        {/* Right Column: Display & History */}
        <div className="lg:col-span-7 space-y-8">
          {isGenerating && history.length === 0 && (
            <div className="bg-white rounded-3xl p-12 flex flex-col items-center justify-center text-center shadow-sm border border-dashed border-blue-200 animate-pulse min-h-[500px]">
              <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                <svg className="animate-spin h-10 w-10 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              </div>
              <h3 className="text-xl font-bold text-gray-700">ذكاؤنا الاصطناعي يقوم بالعمل السحري</h3>
              <p className="text-gray-500 mt-2">نقوم بتحليل منتجك واختيار البيئة التسويقية الأكثر جاذبية...</p>
            </div>
          )}

          {history.length > 0 ? (
            <div className="space-y-8">
              {/* Latest Result */}
              <div className="bg-white rounded-3xl overflow-hidden shadow-xl border border-gray-100">
                <div className="aspect-auto max-h-[600px] overflow-hidden bg-gray-100 flex items-center justify-center relative group">
                  <img 
                    src={history[0].url} 
                    alt="Latest generated product"
                    className="w-full h-full object-contain transition-transform duration-500 hover:scale-105"
                  />
                  <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-10 transition-all duration-300 pointer-events-none"></div>
                </div>
                <div className="p-6 flex flex-col md:flex-row gap-4 justify-between items-center bg-white">
                  <div>
                    <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold mb-2 inline-block">
                      {history[0].style}
                    </span>
                    <p className="text-sm text-gray-600 line-clamp-1">{history[0].prompt}</p>
                  </div>
                  <div className="flex gap-2 w-full md:w-auto">
                    <button 
                      onClick={() => downloadImage(history[0].url, 0)}
                      className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-5 py-2.5 rounded-2xl font-bold hover:bg-blue-700 transition-colors shadow-md"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                      </svg>
                      تحميل
                    </button>
                    <button 
                      onClick={() => {
                        const shareData = { title: 'صورتي التسويقية', text: 'انظر ماذا صنعت بمساعد الذكاء الاصطناعي!', url: window.location.href };
                        if (navigator.share) navigator.share(shareData);
                      }}
                      className="p-2.5 bg-gray-100 text-gray-600 rounded-2xl hover:bg-gray-200 transition-colors"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>

              {/* History Grid */}
              {history.length > 1 && (
                <section>
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
                    <span className="w-2 h-6 bg-slate-400 rounded-full block"></span>
                    التصميمات السابقة
                  </h3>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    {history.slice(1).map((img, idx) => (
                      <div key={img.timestamp} className="relative group bg-white p-2 rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                        <img 
                          src={img.url} 
                          alt="Previous product generation" 
                          className="w-full aspect-square object-cover rounded-xl"
                        />
                        <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-40 transition-all duration-300 flex items-center justify-center opacity-0 group-hover:opacity-100">
                          <button 
                            onClick={() => downloadImage(img.url, idx + 1)}
                            className="bg-white text-blue-600 p-3 rounded-full shadow-lg transform translate-y-4 group-hover:translate-y-0 transition-all duration-300"
                          >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                            </svg>
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                </section>
              )}
            </div>
          ) : !isGenerating && (
            <div className="h-full flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl border-2 border-dashed border-gray-200 min-h-[500px]">
              <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center mb-6 text-gray-400">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-gray-700">كيف تريد البدء؟</h3>
              <p className="text-gray-500 mt-2 max-w-sm">يمكنك رفع صورة لمنتجك وسنقوم بوضعه في بيئة احترافية، أو اكتفِ بوصف المنتج وسنقوم برسمه بالكامل.</p>
            </div>
          )}
        </div>
      </main>

      {/* Camera Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black bg-opacity-90 flex flex-col items-center justify-center p-6">
          <div className="relative w-full max-w-2xl bg-slate-900 rounded-3xl overflow-hidden shadow-2xl">
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              className="w-full aspect-video md:aspect-auto object-cover"
            />
            <div className="absolute bottom-6 left-0 right-0 flex justify-center items-center gap-6">
              <button 
                onClick={stopCamera}
                className="w-12 h-12 bg-white bg-opacity-20 backdrop-blur-md rounded-full flex items-center justify-center text-white border border-white border-opacity-30 hover:bg-opacity-30 transition-all"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
              <button 
                onClick={capturePhoto}
                className="w-20 h-20 bg-white rounded-full border-8 border-gray-300 shadow-inner active:scale-90 transition-transform flex items-center justify-center"
              >
                <div className="w-12 h-12 rounded-full border-2 border-slate-300"></div>
              </button>
              <div className="w-12"></div> {/* Spacer for symmetry */}
            </div>
          </div>
          <p className="text-white mt-6 font-medium">ضع منتجك في إضاءة جيدة ثم التقط الصورة</p>
        </div>
      )}

      {/* Mobile Sticky CTA */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 py-3 px-6 z-50 md:hidden">
        <button
          onClick={handleGenerate}
          disabled={isGenerating}
          className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 ${
            isGenerating ? 'bg-gray-200 text-gray-500' : 'bg-blue-600 text-white'
          }`}
        >
          {isGenerating ? 'جاري العمل...' : productImage ? 'تحويل صورتي' : 'إنشاء صورة'}
        </button>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useRef, useCallback } from 'react';
import { MARKETING_STYLES, ASPECT_RATIOS } from './constants';
import { AspectRatio, GeneratedImage, MarketingStyle } from './types';
import StyleCard from './components/StyleCard';
import { generateProductImage } from './services/geminiService';

const App: React.FC = () => {
  const [description, setDescription] = useState('');
  const [selectedStyle, setSelectedStyle] = useState<MarketingStyle>(MARKETING_STYLES[0]);
  const [selectedRatio, setSelectedRatio] = useState<AspectRatio>("1:1");
  const [isGenerating, setIsGenerating] = useState(false);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [error, setError] = useState<string | null>(null);

  // State for user product image
  const [productImage, setProductImage] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProductImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setShowCamera(true);
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setError('لا يمكن الوصول إلى الكاميرا. تأكد من منح الأذونات اللازمة.');
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0);
        setProductImage(canvas.toDataURL('image/png'));
        stopCamera();
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      setShowCamera(false);
    }
  };

  const handleGenerate = async () => {
    if (!description.trim() && !productImage) {
      setError('يرجى إدخال وصف للمنتج أو إضافة صورة له');
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const imageUrl = await generateProductImage(
        description,
        selectedStyle.promptPrefix,
        selectedRatio,
        productImage || undefined
      );

      const newImage: GeneratedImage = {
        url: imageUrl,
        prompt: description || `صورة منتج بأسلوب ${selectedStyle.name}`,
        style: selectedStyle.name,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImage, ...prev]);

      // Scroll to top of results on mobile
      if (window.innerWidth < 1024) {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } catch (err) {
      setError('حدث خطأ أثناء إنشاء الصورة. يرجى المحاولة مرة أخرى.');
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = (url: string, index: number) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `product-image-${index}.png`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-[#fcfdfe] text-slate-900">
      {/* Header */}
      <header className="sticky top-0 z-[60] glass-effect py-4 px-6 border-b border-gray-100">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-l from-blue-700 to-blue-500">
              مصمم الصور التسويقية
            </h1>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 md:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-start">

          {/* Right/Output Column (Visual Primary on desktop) */}
          <div className="order-1 lg:order-2 space-y-8 min-h-[500px]">
            {isGenerating && (
              <div className="bg-white rounded-3xl p-12 flex flex-col items-center justify-center text-center shadow-sm border border-dashed border-blue-200 animate-pulse min-h-[500px]">
                <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                  <svg className="animate-spin h-10 w-10 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
