import { GoogleGenAI } from "@google/genai";
import { AspectRatio } from "../types";

export const generateProductImage = async (
  productDescription: string,
  stylePrompt: string,
  aspectRatio: AspectRatio,
  productBase64?: string,
  brandLogoBase64?: string
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  let instructions = brandLogoBase64 
    ? `IMPORTANT: I have provided a brand logo. Please incorporate this logo naturally into the final marketing image, perhaps on the product itself or as a subtle watermark in a corner. `
    : "";

  const basePrompt = productBase64 
    ? `${instructions}Take the product shown in the first image and place it in a new professional scene: ${stylePrompt}. Maintain the exact product details and shape. Additional details: ${productDescription}. No text other than the provided logo.`
    : `${instructions}${stylePrompt} Product description: ${productDescription}. The image should strictly follow the style but focus on the product described. No text other than the provided logo if applicable.`;

  const contents: any = {
    parts: [
      { text: basePrompt }
    ]
  };

  // Add product image if exists
  if (productBase64) {
    const cleanProductBase64 = productBase64.split(',')[1] || productBase64;
    contents.parts.unshift({
      inlineData: {
        data: cleanProductBase64,
        mimeType: 'image/png'
      }
    });
  }

  // Add brand logo if exists
  if (brandLogoBase64) {
    const cleanLogoBase64 = brandLogoBase64.split(',')[1] || brandLogoBase64;
    contents.parts.push({
      inlineData: {
        data: cleanLogoBase64,
        mimeType: 'image/png'
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: contents,
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        const base64EncodeString = part.inlineData.data;
        return `data:image/png;base64,${base64EncodeString}`;
      }
    }

    throw new Error("لم يتم العثور على صورة في الاستجابة");
  } catch (error) {
    console.error("خطأ في إنشاء الصورة:", error);
    throw error;
  }
};

import React, { useState, useRef, useCallback } from 'react';
import { MARKETING_STYLES, ASPECT_RATIOS } from './constants';
import { AspectRatio, GeneratedImage, MarketingStyle } from './types';
import StyleCard from './components/StyleCard';
import { generateProductImage } from './services/geminiService';

const App: React.FC = () => {
  const [description, setDescription] = useState('');
  const [selectedStyle, setSelectedStyle] = useState<MarketingStyle>(MARKETING_STYLES[0]);
  const [selectedRatio, setSelectedRatio] = useState<AspectRatio>("1:1");
  const [isGenerating, setIsGenerating] = useState(false);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [error, setError] = useState<string | null>(null);

  // State for user product image and brand logo
  const [productImage, setProductImage] = useState<string | null>(null);
  const [brandLogo, setBrandLogo] = useState<string | null>(null);
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setProductImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setBrandLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setShowCamera(true);
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      setError('لا يمكن الوصول إلى الكاميرا. تأكد من منح الأذونات اللازمة.');
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0);
        setProductImage(canvas.toDataURL('image/png'));
        stopCamera();
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      setShowCamera(false);
    }
  };

  const handleGenerate = async () => {
    if (!description.trim() && !productImage) {
      setError('يرجى إدخال وصف للمنتج أو إضافة صورة له');
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const imageUrl = await generateProductImage(
        description,
        selectedStyle.promptPrefix,
        selectedRatio,
        productImage || undefined,
        brandLogo || undefined
      );

      const newImage: GeneratedImage = {
        url: imageUrl,
        prompt: description || `صورة منتج بأسلوب ${selectedStyle.name}`,
        style: selectedStyle.name,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImage, ...prev]);

      if (window.innerWidth < 1024) {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } catch (err) {
      setError('حدث خطأ أثناء إنشاء الصورة. يرجى المحاولة مرة أخرى.');
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = (url: string, index: number) => {
    const link = document.createElement('a');
    link.href = url;
    link.download = `product-image-${index}.png`;
    link.click();
  };

  return (
    <div className="min-h-screen bg-[#fcfdfe] text-slate-900">
      {/* Header */}
      <header className="sticky top-0 z-[60] glass-effect py-4 px-6 border-b border-gray-100">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            {/* Branding Logo Upload (Top Right in RTL) */}
            <div className="relative group">
              <input 
                type="file" 
                ref={logoInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleLogoUpload} 
              />
              <button 
                onClick={() => logoInputRef.current?.click()}
                className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all border-2 overflow-hidden shadow-sm ${
                  brandLogo ? 'border-blue-500 bg-white' : 'border-dashed border-gray-300 bg-gray-50 hover:bg-gray-100'
                }`}
                title="اضافة شعار البراند"
              >
                {brandLogo ? (
                  <img src={brandLogo} alt="Logo" className="w-full h-full object-contain" />
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                  </svg>
                )}
              </button>
              {brandLogo && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setBrandLogo(null); }}
                  className="absolute -top-1 -right-1 bg-red-500 text-white p-0.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity shadow-sm"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                </button>
              )}
            </div>

            <div className="flex items-center gap-3 pr-2 border-r border-gray-100">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                </svg>
              </div>
              <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-l from-blue-700 to-blue-500">
                مصمم الصور التسويقية
              </h1>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 md:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-start">

          {/* Output Column */}
          <div className="order-1 lg:order-2 space-y-8 min-h-[500px]">
            {isGenerating && (
              <div className="bg-white rounded-3xl p-12 flex flex-col items-center justify-center text-center shadow-sm border border-dashed border-blue-200 animate-pulse min-h-[500px]">
                <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                  <svg className="animate-spin h-10 w-10 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-700">ذكاؤنا الاصطناعي يقوم بالعمل السحري</h3>
                <p className="text-gray-500 mt-2">نقوم بتحليل منتجك ودمج شعارك في التصميم...</p>
              </div>
            )}

            {!isGenerating && history.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center p-12 text-center bg-white rounded-3xl border border-gray-100 min-h-[500px] shadow-sm">
                <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mb-6 text-blue-400">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-700">معاينة التصميم ستظهر هنا</h3>
                <p className="text-gray-500 mt-2 max-w-sm">قم بتعبئة بيانات المنتج، أضف شعارك، وابدأ الإبداع.</p>
              </div>
            )}

            {history.length > 0 && !isGenerating && (
              <div className="space-y-8">
                <div className="bg-white rounded-3xl overflow-hidden shadow-2xl border border-gray-100">
                  <div className="aspect-auto max-h-[700px] overflow-hidden bg-gray-50 flex items-center justify-center relative group">
                    <img 
                      src={history[0].url} 
                      alt="Latest generated product"
                      className="w-full h-full object-contain"
                    />
                  </div>
                  <div className="p-6 flex flex-col md:flex-row gap-4 justify-between items-center bg-white border-t border-gray-50">
                    <div>
                      <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold mb-2 inline-block">
                        {history[0].style}
                      </span>
                      <p className="text-sm text-gray-600 line-clamp-1">{history[0].prompt}</p>
                    </div>
                    <div className="flex gap-2 w-full md:w-auto">
                      <button 
                        onClick={() => downloadImage(history[0].url, 0)}
                        className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg active:scale-95"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                        تحميل الإعلان
                      </button>
                    </div>
                  </div>
                </div>

                {history.length > 1 && (
                  <section className="pt-4">
                    <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-gray-700">
                      <span className="w-2 h-5 bg-gray-300 rounded-full block"></span>
                      التصميمات السابقة
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                      {history.slice(1).map((img, idx) => (
                        <div key={img.timestamp} className="relative group bg-white p-2 rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                          <img 
                            src={img.url} 
                            alt="Previous product generation" 
                            className="w-full aspect-square object-cover rounded-xl"
                          />
                          <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-40 transition-all duration-300 flex items-center justify-center opacity-0 group-hover:opacity-100">
                            <button 
                              onClick={() => downloadImage(img.url, idx + 1)}
                              className="bg-white text-blue-600 p-3 rounded-full shadow-lg transform translate-y-4 group-hover:translate-y-0 transition-all duration-300"
                            >
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                              </svg>
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                )}
              </div>
            )}
          </div>

          {/* Input Column */}
          <div className="order-2 lg:order-1 lg:sticky lg:top-24 self-start">
            <section className="bg-white p-6 md:p-8 rounded-[32px] shadow-xl border border-gray-100">
              <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                إعدادات الإعلان
              </h2>

              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">صورة المنتج الحقيقية</label>
                  {!productImage ? (
                    <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="flex flex-col items-center justify-center p-6 bg-blue-50/50 border-2 border-dashed border-blue-100 rounded-2xl hover:bg-blue-100/50 transition-colors group"
                      >
                        <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm mb-2 text-blue-500 group-hover:scale-110 transition-transform">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                          </svg>
                        </div>
                        <span className="text-xs font-bold text-blue-700">رفع صورة</span>
                      </button>
                      <button 
                        onClick={startCamera}
                        className="flex flex-col items-center justify-center p-6 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl hover:bg-gray-100 transition-colors group"
                      >
                        <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm mb-2 text-gray-400 group-hover:scale-110 transition-transform">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                          </svg>
                        </div>
                        <span className="text-xs font-bold text-gray-500">التقاط صورة</span>
                      </button>
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        className="hidden" 
                        accept="image/*" 
                        onChange={handleFileUpload} 
                      />
                    </div>
                  ) : (
                    <div className="relative rounded-2xl overflow-hidden aspect-video bg-gray-50 border border-gray-100 group">
                      <img src={productImage} alt="User product" className="w-full h-full object-contain" />
                      <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-20 transition-all flex items-center justify-center">
                        <button 
                          onClick={() => setProductImage(null)}
                          className="bg-red-500 text-white p-3 rounded-full shadow-xl hover:bg-red-600 transform scale-0 group-hover:scale-100 transition-transform"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                          </svg>
                        </button>
                      </div>
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2">وصف المنتج (نصي)</label>
                  <textarea
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    placeholder="مثال: ساعة يد أنيقة، حقيبة جلدية فاخرة..."
                    className="w-full h-24 p-4 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none text-right placeholder-gray-400"
                    dir="rtl"
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">اختر نمط الإعلان</label>
                  <div className="grid grid-cols-2 gap-3">
                    {MARKETING_STYLES.map((style) => (
                      <StyleCard
                        key={style.id}
                        style={style}
                        isSelected={selectedStyle.id === style.id}
                        onClick={() => setSelectedStyle(style)}
                      />
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-3">الأبعاد</label>
                  <div className="flex flex-wrap gap-2">
                    {ASPECT_RATIOS.map((ratio) => (
                      <button
                        key={ratio.value}
                        onClick={() => setSelectedRatio(ratio.value as AspectRatio)}
                        className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all ${
                          selectedRatio === ratio.value
                            ? 'bg-blue-600 text-white shadow-lg shadow-blue-200'
                            : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-transparent'
                        }`}
                      >
                        {ratio.label}
                      </button>
                    ))}
                  </div>
                </div>

                {error && (
                  <div className="p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-sm flex items-center gap-3">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 shrink-0" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    {error}
                  </div>
                )}

                <button
                  onClick={handleGenerate}
                  disabled={isGenerating}
                  className={`w-full py-5 rounded-2xl font-bold text-xl shadow-xl transition-all flex items-center justify-center gap-3 ${
                    isGenerating 
                    ? 'bg-gray-100 cursor-not-allowed text-gray-400 shadow-none' 
                    : 'bg-gradient-to-r from-blue-700 to-blue-600 text-white hover:shadow-2xl hover:-translate-y-0.5 active:translate-y-0'
                  }`}
                >
                  {isGenerating ? (
                    <>
                      <svg className="animate-spin h-6 w-6 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      جاري التصميم...
                    </>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                      </svg>
                      {productImage ? 'تحويل صورتي إلى إعلان' : 'إنشاء إعلان جديد'}
                    </>
                  )}
                </button>
              </div>
            </section>
          </div>
        </div>
      </main>

      {/* Camera Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] bg-black bg-opacity-95 flex flex-col items-center justify-center p-6 backdrop-blur-sm">
          <div className="relative w-full max-w-2xl bg-slate-900 rounded-3xl overflow-hidden shadow-2xl border border-white/10">
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              className="w-full aspect-video md:aspect-auto object-cover"
            />
            <div className="absolute bottom-8 left-0 right-0 flex justify-center items-center gap-8">
              <button 
                onClick={stopCamera}
                className="w-14 h-14 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center text-white border border-white/20 hover:bg-white/20 transition-all active:scale-90"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
              <button 
                onClick={capturePhoto}
                className="w-20 h-20 bg-white rounded-full border-4 border-white/30 p-1 active:scale-95 transition-all shadow-[0_0_20px_rgba(255,255,255,0.3)]"
              >
                <div className="w-full h-full rounded-full border-2 border-slate-900 bg-white"></div>
              </button>
              <div className="w-14"></div>
            </div>
          </div>
          <p className="text-white mt-8 font-medium text-lg">ضع منتجك في إضاءة جيدة ثم التقط الصورة</p>
        </div>
      )}

      {/* Mobile Sticky CTA */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 py-4 px-6 z-50 lg:hidden shadow-[0_-5px_15px_rgba(0,0,0,0.05)]">
        <button
          onClick={handleGenerate}
          disabled={isGenerating}
          className={`w-full py-4 rounded-2xl font-bold flex items-center justify-center gap-2 text-lg ${
            isGenerating ? 'bg-gray-100 text-gray-400' : 'bg-blue-600 text-white'
          }`}
        >
          {isGenerating ? 'جاري العمل...' : productImage ? 'تحويل صورتي' : 'إنشاء إعلان'}
        </button>
      </footer>
    </div>
  );
};

export default App;

export type AspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";
export type LogoPosition = "top-right" | "top-left" | "bottom-right" | "bottom-left";

export interface MarketingStyle {
  id: string;
  name: string;
  description: string;
  promptPrefix: string;
  icon: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
  style: string;
  timestamp: number;
}

import React, { useState, useRef, useCallback } from 'react';
import { MARKETING_STYLES, ASPECT_RATIOS } from './constants';
import { AspectRatio, GeneratedImage, MarketingStyle, LogoPosition } from './types';
import StyleCard from './components/StyleCard';
import { generateProductImage } from './services/geminiService';

const App: React.FC = () => {
  const [description, setDescription] = useState('');
  const [selectedStyle, setSelectedStyle] = useState<MarketingStyle>(MARKETING_STYLES[0]);
  const [selectedRatio, setSelectedRatio] = useState<AspectRatio>("1:1");
  const [isGenerating, setIsGenerating] = useState(false);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [error, setError] = useState<string | null>(null);

  // Brand Logo and Product Image State
  const [productImage, setProductImage] = useState<string | null>(null);
  const [brandLogo, setBrandLogo] = useState<string | null>(null);
  const [logoPosition, setLogoPosition] = useState<LogoPosition>("top-right");
  const [logoSize, setLogoSize] = useState<number>(15); // Percentage of width
  const [showCamera, setShowCamera] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const logoInputRef = useRef<HTMLInputElement>(null);
  const logoSidebarInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setProductImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setBrandLogo(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setShowCamera(true);
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setError('لا يمكن الوصول إلى الكاميرا. تأكد من منح الأذونات اللازمة.');
      setShowCamera(false);
    }
  };

  const capturePhoto = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0);
        setProductImage(canvas.toDataURL('image/png'));
        stopCamera();
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      setShowCamera(false);
    }
  };

  const handleGenerate = async () => {
    if (!description.trim() && !productImage) {
      setError('يرجى إدخال وصف للمنتج أو إضافة صورة له');
      return;
    }
    setIsGenerating(true);
    setError(null);
    try {
      // Note: We send the logo to AI for blending, but we will also overlay it for sharpness in the final download
      const imageUrl = await generateProductImage(
        description,
        selectedStyle.promptPrefix,
        selectedRatio,
        productImage || undefined,
        brandLogo || undefined
      );
      const newImage: GeneratedImage = {
        url: imageUrl,
        prompt: description || `صورة منتج بأسلوب ${selectedStyle.name}`,
        style: selectedStyle.name,
        timestamp: Date.now(),
      };
      setHistory((prev) => [newImage, ...prev]);
      if (window.innerWidth < 1024) window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      setError('حدث خطأ أثناء إنشاء الصورة. يرجى المحاولة مرة أخرى.');
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadImage = async (imgUrl: string, filename: string) => {
    if (!brandLogo) {
      const link = document.createElement('a');
      link.href = imgUrl;
      link.download = `${filename}.png`;
      link.click();
      return;
    }

    // Merge Image and Logo using Canvas for high quality
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const mainImg = new Image();
    const logoImg = new Image();

    await Promise.all([
      new Promise(res => { mainImg.onload = res; mainImg.src = imgUrl; }),
      new Promise(res => { logoImg.onload = res; logoImg.src = brandLogo; })
    ]);

    canvas.width = mainImg.width;
    canvas.height = mainImg.height;
    ctx.drawImage(mainImg, 0, 0);

    const lSize = (canvas.width * logoSize) / 100;
    const padding = canvas.width * 0.05;
    const lWidth = lSize;
    const lHeight = (logoImg.height / logoImg.width) * lWidth;

    let lx = 0, ly = 0;
    switch(logoPosition) {
      case 'top-right': lx = canvas.width - lWidth - padding; ly = padding; break;
      case 'top-left': lx = padding; ly = padding; break;
      case 'bottom-right': lx = canvas.width - lWidth - padding; ly = canvas.height - lHeight - padding; break;
      case 'bottom-left': lx = padding; ly = canvas.height - lHeight - padding; break;
    }

    ctx.drawImage(logoImg, lx, ly, lWidth, lHeight);

    const link = document.createElement('a');
    link.href = canvas.toDataURL('image/png');
    link.download = `${filename}.png`;
    link.click();
  };

  const getLogoPositionClasses = () => {
    switch(logoPosition) {
      case 'top-right': return 'top-6 right-6';
      case 'top-left': return 'top-6 left-6';
      case 'bottom-right': return 'bottom-6 right-6';
      case 'bottom-left': return 'bottom-6 left-6';
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfdfe] text-slate-900 pb-20 lg:pb-0">
      <header className="sticky top-0 z-[60] glass-effect py-4 px-6 border-b border-gray-100">
        <div className="max-w-[1600px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-4">
            <div className="relative group">
              <input type="file" ref={logoInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
              <button 
                onClick={() => logoInputRef.current?.click()}
                className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all border-2 overflow-hidden shadow-sm ${
                  brandLogo ? 'border-blue-500 bg-white' : 'border-dashed border-gray-300 bg-gray-50 hover:bg-gray-100'
                }`}
              >
                {brandLogo ? <img src={brandLogo} alt="Logo" className="w-full h-full object-contain" /> : <svg className="h-6 w-6 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>}
              </button>
            </div>
            <div className="flex items-center gap-3 pr-2 border-r border-gray-100">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></div>
              <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-l from-blue-700 to-blue-500">مصمم الصور التسويقية</h1>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto px-4 md:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-start">
          {/* Output Column */}
          <div className="order-1 lg:order-2 space-y-8 min-h-[500px]">
            {isGenerating ? (
              <div className="bg-white rounded-[32px] p-12 flex flex-col items-center justify-center text-center shadow-sm border border-dashed border-blue-200 animate-pulse min-h-[500px]">
                <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center mb-6"><svg className="animate-spin h-10 w-10 text-blue-500" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg></div>
                <h3 className="text-xl font-bold text-gray-700">جاري الإبداع...</h3>
              </div>
            ) : history.length > 0 ? (
              <div className="space-y-8">
                <div className="bg-white rounded-[40px] overflow-hidden shadow-2xl border border-gray-100 relative group">
                  <div className="aspect-auto max-h-[700px] overflow-hidden bg-gray-50 flex items-center justify-center relative">
                    <img src={history[0].url} className="w-full h-full object-contain" />
                    {brandLogo && (
                      <div className={`absolute ${getLogoPositionClasses()} pointer-events-none transition-all duration-300`} style={{ width: `${logoSize}%` }}>
                        <img src={brandLogo} className="w-full h-auto drop-shadow-lg" />
                      </div>
